#include "jerico/bookshelf.hpp"
#include "jerico/evaluate.hpp"
#include "jerico/export.hpp"
#include "jerico/bookshelf_materials.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{std::string recipe,out="bookshelf-out";int resolution=384;bool geom=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--recipe"&&i+1<argc)recipe=argv[++i];else if(a=="--out"&&i+1<argc)out=argv[++i];else if(a=="--bake"&&i+1<argc)resolution=std::stoi(argv[++i]);else if(a=="--geometry-only")geom=true;else throw std::invalid_argument("Usage: jerico_bookshelf [--recipe JSON] --out DIR [--bake 384] [--geometry-only]");}jerico::Json r=jerico::Json::object();if(!recipe.empty()){std::ifstream f(recipe);if(!f)throw std::runtime_error("Cannot read recipe");f>>r;}auto raw=jerico::build_bookshelf(r);auto issues=jerico::validate_bookshelf(raw);if(!issues.empty())throw std::runtime_error(issues.dump(2));auto scene=jerico::evaluate_scene(raw);issues=jerico::validate_scene(scene);if(!issues.empty())throw std::runtime_error(issues.dump(2));std::filesystem::create_directories(out);std::ofstream(out+"/recipe.json")<<scene["recipe"].dump(2);if(!geom){jerico::bake_bookshelf_materials(scene,out+"/native-textures",resolution);jerico::write_glb(scene,out+"/bookshelf.glb");jerico::write_obj_mtl(scene,out+"/bookshelf.obj");}std::ofstream(out+"/scene.json")<<scene.dump();size_t triangles=0;for(auto&p:scene["parts"])for(auto&f:p["faces"])triangles+=f.size()-2;jerico::Json metrics={{"parts",scene["parts"].size()},{"items",scene["metadata"]["items"].size()},{"triangles",triangles},{"texture_resolution",geom?0:resolution},{"native_cpp",true},{"layout_validation",issues}};std::ofstream(out+"/metrics.json")<<metrics.dump(2);std::cout<<metrics.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
